{
  "name": "Rigol DS1054Z数字示波器",
  "name_en": "Rigol DS1054Z Digital Oscilloscope",
  "manufacturer": "Rigol",
  "description": "这是一台台式数字示波器，通过USBTMC接口进行控制，用于采集和显示电信号波形，并可进行通道配置、触发设置、时基调整、采样与存储深度查询、波形数据读取以及屏幕截图获取，适合实验中的通用电信号观测与分析。",
  "description_en": "This is a bench digital oscilloscope controlled over USBTMC, used to acquire and display electrical waveforms. It supports channel configuration, trigger setup, timebase adjustment, sampling and memory-depth queries, waveform data retrieval, and screenshot capture for general laboratory signal observation and analysis.",
  "tag_hints": [
    "digital oscilloscope",
    "waveform acquisition",
    "USBTMC",
    "trigger control",
    "timebase setting",
    "channel scaling",
    "waveform export",
    "RMS voltage measurement"
  ],
  "actions": [
    {
      "action_name": "auto-autoscale",
      "description": "自动调整示波器设置以稳定显示波形",
      "description_en": "automatically adjust oscilloscope settings to stabilize the waveform display"
    },
    {
      "action_name": "auto-clear",
      "description": "清除示波器显示或采集状态",
      "description_en": "clear the oscilloscope display or acquisition state"
    },
    {
      "action_name": "auto-run",
      "description": "开始连续采集波形",
      "description_en": "start continuous waveform acquisition"
    },
    {
      "action_name": "auto-stop",
      "description": "停止波形采集",
      "description_en": "stop waveform acquisition"
    },
    {
      "action_name": "auto-force",
      "description": "强制触发一次采集",
      "description_en": "force a trigger event"
    },
    {
      "action_name": "auto-set_single_shot",
      "description": "设置单次采集模式",
      "description_en": "set single-shot acquisition mode"
    },
    {
      "action_name": "auto-set_averaging",
      "description": "设置平均次数",
      "description_en": "set averaging count"
    },
    {
      "action_name": "auto-set_averaging_mode",
      "description": "设置平均采集模式",
      "description_en": "set averaging acquisition mode"
    },
    {
      "action_name": "auto-set_normal_mode",
      "description": "设置普通采集模式",
      "description_en": "set normal acquisition mode"
    },
    {
      "action_name": "auto-set_high_resolution_mode",
      "description": "设置高分辨率采集模式",
      "description_en": "set high-resolution acquisition mode"
    },
    {
      "action_name": "auto-set_peak_mode",
      "description": "设置峰值检测模式",
      "description_en": "set peak-detect mode"
    },
    {
      "action_name": "auto-set_memory_depth",
      "description": "设置存储深度",
      "description_en": "set memory depth"
    },
    {
      "action_name": "auto-selected_channel",
      "description": "选择当前活动通道",
      "description_en": "select the active channel"
    },
    {
      "action_name": "auto-get_id",
      "description": "获取设备标识",
      "description_en": "get device identification"
    },
    {
      "action_name": "auto-get_averaging",
      "description": "获取平均次数",
      "description_en": "get averaging count"
    },
    {
      "action_name": "auto-get_mode",
      "description": "获取采集模式",
      "description_en": "get acquisition mode"
    },
    {
      "action_name": "auto-get_sampling_rate",
      "description": "获取采样率",
      "description_en": "get sampling rate"
    },
    {
      "action_name": "auto-get_memory_depth",
      "description": "获取存储深度",
      "description_en": "get memory depth"
    },
    {
      "action_name": "auto-get_channels_enabled",
      "description": "获取已启用的通道",
      "description_en": "get enabled channels"
    },
    {
      "action_name": "auto-get_screenshot",
      "description": "获取示波器屏幕截图",
      "description_en": "get an oscilloscope screenshot"
    },
    {
      "action_name": "auto-get_voltage_rms_V",
      "description": "获取电压均方根值（伏）",
      "description_en": "get RMS voltage in volts"
    },
    {
      "action_name": "auto-select_channel",
      "description": "选择通道",
      "description_en": "select the channel"
    },
    {
      "action_name": "auto-get_coupling",
      "description": "获取输入耦合方式",
      "description_en": "get input coupling"
    },
    {
      "action_name": "auto-set_coupling",
      "description": "设置输入耦合方式",
      "description_en": "set input coupling"
    },
    {
      "action_name": "auto-enable",
      "description": "启用通道",
      "description_en": "enable the channel"
    },
    {
      "action_name": "auto-disable",
      "description": "禁用通道",
      "description_en": "disable the channel"
    },
    {
      "action_name": "auto-enabled",
      "description": "获取通道是否已启用",
      "description_en": "get whether the channel is enabled"
    },
    {
      "action_name": "auto-disabled",
      "description": "获取通道是否已禁用",
      "description_en": "get whether the channel is disabled"
    },
    {
      "action_name": "auto-get_offset_V",
      "description": "获取垂直偏置（伏）",
      "description_en": "get vertical offset in volts"
    },
    {
      "action_name": "auto-set_offset_V",
      "description": "设置垂直偏置（伏）",
      "description_en": "set vertical offset in volts"
    },
    {
      "action_name": "auto-get_range_V",
      "description": "获取垂直量程（伏）",
      "description_en": "get vertical range in volts"
    },
    {
      "action_name": "auto-set_range_V",
      "description": "设置垂直量程（伏）",
      "description_en": "set vertical range in volts"
    },
    {
      "action_name": "auto-set_vertical_scale_V",
      "description": "设置垂直刻度（伏/格）",
      "description_en": "set vertical scale in volts per division"
    },
    {
      "action_name": "auto-get_probe_ratio",
      "description": "获取探头倍率",
      "description_en": "get probe ratio"
    },
    {
      "action_name": "auto-set_probe_ratio",
      "description": "设置探头倍率",
      "description_en": "set probe ratio"
    },
    {
      "action_name": "auto-get_units",
      "description": "获取通道单位",
      "description_en": "get channel units"
    },
    {
      "action_name": "auto-set_units",
      "description": "设置通道单位",
      "description_en": "set channel units"
    },
    {
      "action_name": "auto-get_data_premable",
      "description": "获取波形数据前导信息",
      "description_en": "get waveform data preamble"
    },
    {
      "action_name": "auto-get_data",
      "description": "获取波形数据",
      "description_en": "get waveform data"
    },
    {
      "action_name": "auto-get_trigger_level_V",
      "description": "获取触发电平（伏）",
      "description_en": "get trigger level in volts"
    },
    {
      "action_name": "auto-set_trigger_level_V",
      "description": "设置触发电平（伏）",
      "description_en": "set trigger level in volts"
    },
    {
      "action_name": "auto-get_trigger_holdoff_s",
      "description": "获取触发保持时间（秒）",
      "description_en": "get trigger holdoff in seconds"
    },
    {
      "action_name": "auto-set_trigger_holdoff_s",
      "description": "设置触发保持时间（秒）",
      "description_en": "set trigger holdoff in seconds"
    },
    {
      "action_name": "auto-get_timebase_scale_s_div",
      "description": "获取时基刻度（秒/格）",
      "description_en": "get timebase scale in seconds per division"
    },
    {
      "action_name": "auto-set_timebase_scale_s_div",
      "description": "设置时基刻度（秒/格）",
      "description_en": "set timebase scale in seconds per division"
    },
    {
      "action_name": "auto-get_timebase_mode",
      "description": "获取时基模式",
      "description_en": "get timebase mode"
    },
    {
      "action_name": "auto-set_timebase_mode",
      "description": "设置时基模式",
      "description_en": "set timebase mode"
    },
    {
      "action_name": "auto-get_timebase_offset_s",
      "description": "获取时基偏移（秒）",
      "description_en": "get timebase offset in seconds"
    },
    {
      "action_name": "auto-set_timebase_offset_s",
      "description": "设置时基偏移（秒）",
      "description_en": "set timebase offset in seconds"
    }
  ]
}

